"use client";

import { useState, useEffect } from 'react';
import { navLinks } from '@/constants';

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [inHero, setInHero] = useState(true);
  const [barVisible, setBarVisible] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setBarVisible(true), 80);
    const onScroll = () => setInHero(window.scrollY < window.innerHeight - 80);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => { clearTimeout(t); window.removeEventListener('scroll', onScroll); };
  }, []);

  const handleNavClick = (href) => {
    setMenuOpen(false);
    setTimeout(() => {
      const el = href === '#home' ? document.documentElement : document.querySelector(href);
      el?.scrollIntoView({ behavior: 'smooth' });
    }, menuOpen ? 30 : 0);
  };

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 flex items-center justify-between px-6 md:px-16 py-2 transition-all duration-500 ${barVisible ? 'opacity-100' : 'opacity-0'} ${inHero ? 'bg-transparent' : 'bg-accent shadow-lg'}`}>
      <div onClick={() => handleNavClick('#home')} className="flex items-center text-white font-extrabold text-lg cursor-pointer">
        {/* Panggil dari folder public */}
        <img src="/logo-indri.svg" alt="logo indri" className="h-12 w-auto" />
        <span className="ml-2">Indri Collection</span>
      </div>

      <div className="hidden md:flex gap-8">
        {navLinks.map((link) => (
          <button key={link.label} onClick={() => handleNavClick(link.href)} className="text-white font-medium text-sm hover:underline">
            {link.label}
          </button>
        ))}
      </div>
    </nav>
  );
}