"use client";

import Image from 'next/image';
import SectionHeader from '@/components/ui/section-header';
import { statistics } from '@/constants';
import aboutImg from '@/app/assets/images/About.webp';
import { useScrollReveal } from '@/hooks/use-scroll-reveal';

export default function AboutUs() {
  const [sectionRef, isVisible] = useScrollReveal(0.1);

  const fade = (delay = '0ms', fromX = null) => ({
    opacity: isVisible ? 1 : 0,
    transform: isVisible
      ? 'translate(0,0)'
      : fromX ? `translateX(${fromX})` : 'translateY(20px)',
    transition: `opacity 650ms ease ${isVisible ? delay : '0ms'}, transform 650ms ease ${isVisible ? delay : '0ms'}`,
  });

  return (
    <section id="about-us" ref={sectionRef} className="w-full py-24 bg-secondary relative overflow-hidden">
      <div className="container mx-auto px-4 md:px-8 max-w-6xl">
        <div style={fade('0ms')}><SectionHeader title="Tentang" highlightedText="Kami" /></div>

        <div className="flex flex-col md:flex-row gap-16 items-center mt-12">
          <div className="md:w-1/2 space-y-6" style={fade('150ms', '-30px')}>
            <p className="text-gray-700 leading-relaxed font-light">Indri Collection lahir dari keyakinan sederhana, bahwa pakaian yang indah bisa diciptakan oleh siapa saja.</p>
            <p className="text-gray-700 leading-relaxed font-light">Kami adalah konveksi asal Malang yang memberdayakan teman-teman disabilitas.</p>
            
            <div className="flex gap-6 pt-6">
              {statistics.map((stat, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 min-w-[140px]" 
                  style={{ opacity: isVisible ? 1 : 0, transition: `opacity 500ms ease ${350 + i * 100}ms` }}>
                  <h3 className="text-3xl font-bold text-highlight mb-1">{stat.value}</h3>
                  <p className="text-sm text-gray-500 font-medium">{stat.label}</p>
                </div>
              ))}
            </div>
          </div>

          <div className="md:w-1/2 relative" style={fade('250ms', '30px')}>
            <div className="rounded-3xl overflow-hidden shadow-2xl border-8 border-white transition-transform duration-400">
              <Image
                src={aboutImg}
                alt="Indri Collection Store"
                width={600}
                height={500}
                className="w-full h-[500px] object-cover"
              />
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}